import { useState } from "react";
import { useApp } from "../../context/AppContext";
import { useMesaj } from "../../context/MesajContext";
import { EmptyState, Pill } from "../../components/UI";
import ChatSayfasi from "../../components/ChatSayfasi";

export function SeferlerSayfasi() {
  const { seferler, konusmaOluştur, oturum } = useApp();
  const [seciliSefer, setSeciliSefer] = useState(null);
  const [konusmaIdMap, setKonusmaIdMap] = useState({}); // Sefer ID -> Konuşma ID map

  const aktifSeferler = seferler.filter(s => s.durum === "yolda" || s.durum === "teslima_bekleniyor");
  const bitmisSeferler = seferler.filter(s => s.durum === "tamamlandı");

  const konusmaAc = (sefer) => {
    const newConversationId = konusmaOluştur({
      partnerId: sefer.olusturan,
      partnerAd: sefer.olusturan,
      partnerRol: "issiz",
      baslik: `${sefer.yuk} - ${sefer.nereden} → ${sefer.nereye}`,
      resim: "https://api.dicebear.com/7.x/initials/svg?seed=" + sefer.olusturan.substring(0, 2).toUpperCase()
    });
    setKonusmaIdMap(prev => ({ ...prev, [sefer.id]: newConversationId }));
    return newConversationId;
  };

  if (aktifSeferler.length === 0 && bitmisSeferler.length === 0) {
    return (
      <div className="scroll-content">
        <div className="section-title">SEFERLERİM</div>
        <EmptyState icon="✈️" text="Henüz bir seferiniz yok" />
      </div>
    );
  }

  return (
    <div className="scroll-content">
      {aktifSeferler.length > 0 && (
        <>
          <div className="section-title">AKTİF SEFERLER ({aktifSeferler.length})</div>
          {aktifSeferler.map(sefer => (
            <div key={sefer.id} className="card" style={{ marginBottom: 10, borderLeft: "3px solid var(--yesil)" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 10 }}>
                <div className="display" style={{ fontSize: 18 }}>{sefer.yuk}</div>
                <span className="pill pill-green" style={{ textTransform: "capitalize" }}>{sefer.durum.replace("_", " ")}</span>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
                <span style={{ fontWeight: 600 }}>{sefer.nereden}</span>
                <span style={{ color: "var(--turuncu)" }}>—→</span>
                <span style={{ fontWeight: 600 }}>{sefer.nereye}</span>
              </div>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 6, marginBottom: 10 }}>
                <div style={{ background: "var(--bg2)", borderRadius: "var(--r)", padding: "8px 10px", textAlign: "center" }}>
                  <div style={{ fontSize: 12, color: "var(--text3)" }}>Plaka</div>
                  <div style={{ fontSize: 14, fontWeight: 600 }}>{sefer.plaka}</div>
                </div>
                <div style={{ background: "var(--bg2)", borderRadius: "var(--r)", padding: "8px 10px", textAlign: "center" }}>
                  <div style={{ fontSize: 12, color: "var(--text3)" }}>Ücret</div>
                  <div style={{ fontSize: 14, fontWeight: 600 }}>₺{sefer.ucret.toLocaleString()}</div>
                </div>
                <div style={{ background: "var(--bg2)", borderRadius: "var(--r)", padding: "8px 10px", textAlign: "center" }}>
                  <div style={{ fontSize: 12, color: "var(--text3)" }}>Tonaj</div>
                  <div style={{ fontSize: 14, fontWeight: 600 }}>{sefer.ton > 0 ? `${sefer.ton} Ton` : "Serbest"}</div>
                </div>
              </div>
              <div style={{ display: "flex", gap: 8 }}>
                <button
                  onClick={() => konusmaAc(sefer)}
                  className="btn btn-primary"
                  style={{ flex: 1, fontSize: 13, padding: "10px" }}
                >
                  💬 Konuş
                </button>
              </div>
            </div>
          ))}
        </>
      )}

      {bitmisSeferler.length > 0 && (
        <>
          <div className="section-title" style={{ marginTop: 20 }}>GEÇMİŞ SEFERLER ({bitmisSeferler.length})</div>
          {bitmisSeferler.map(sefer => (
            <div key={sefer.id} className="card" style={{ marginBottom: 8 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                <div>
                  <div style={{ fontWeight: 600, fontSize: 14 }}>{sefer.yuk}</div>
                  <div style={{ fontSize: 12, color: "var(--text3)", marginTop: 2 }}>{sefer.nereden} → {sefer.nereye} • {sefer.tarih}</div>
                  <div style={{ fontSize: 12, color: "var(--text3)", marginTop: 2 }}>Kamyoncu: {sefer.kamyoncu} • Plaka: {sefer.plaka}</div>
                </div>
                <div style={{ textAlign: "right" }}>
                  <div style={{ color: "var(--yesil)", fontWeight: 600 }}>₺{sefer.ucret.toLocaleString()}</div>
                  <span className="pill pill-green" style={{ fontSize: 10 }}>✓ Tamamlandı</span>
                </div>
              </div>
              {sefer.belgeler.length > 0 && (
                <div style={{ marginTop: 10, display: "flex", gap: 6, flexWrap: "wrap" }}>
                  {sefer.belgeler.map((b, i) => (
                    <div key={i} style={{ background: "var(--bg2)", borderRadius: "var(--r)", padding: "8px 12px", fontSize: 12, display: "flex", alignItems: "center", gap: 6 }}>
                      {b.tip === "img" ? "🖼️" : "📄"} {b.ad}
                    </div>
                  ))}
                </div>
              )}
              {sefer.odemeDurumu === "odendi" && (
                <div style={{ marginTop: 8, fontSize: 12, color: "var(--yesil)" }}>💰 Ödeme tamamlandı - {sefer.odemeTarihi}</div>
              )}
            </div>
          ))}
        </>
      )}
    </div>
  );
}

export function MesajlarSayfasi({ onGeri }) {
  const { oturum } = useApp();
  const { konusmalar } = useMesaj();
  const [secili, setSecili] = useState(null);

  if (secili) {
    const konusma = konusmalar.find(k => k.id === secili);
    if (!konusma) {
      console.log("Konuşma bulunamadı, çıkılıyor:", secili);
      return null;
    }
    return <ChatSayfasi konusmaId={secili} onGeri={() => setSecili(null)} isKamyoncu={oturum?.rol === "kamyoncu"} />;
  }

  return (
    <div className="scroll-content">
      <div className="section-title">MESAJLAR ({konusmalar.length})</div>
      {konusmalar.length === 0 ? (
        <div style={{ textAlign: "center", padding: "40px 0", color: "var(--text3)" }}>
          <div style={{ fontSize: 40, marginBottom: 12 }}>💬</div>
          <div>Henüz mesaj yok</div>
        </div>
      ) : (
        konusmalar.map(k => (
          <div key={k.id} className="card" style={{ marginBottom: 8, display: "flex", alignItems: "center", gap: 12, cursor: "pointer" }} onClick={() => setSecili(k.id)}>
            <div style={{ width: 42, height: 42, borderRadius: "50%", background: "var(--bg3)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18, flexShrink: 0 }}>
              {k.partnerRol === "kamyoncu" ? "🚛" : "🏢"}
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontWeight: 600, fontSize: 14 }}>{k.partnerAd}</div>
              <div style={{ fontSize: 12, color: "var(--text3)", marginTop: 2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                {k.mesajlar.length > 0 ? (k.mesajlar[k.mesajlar.length - 1].metin || "📄 Dosya gönderildi") : (k.baslik || "")}
              </div>
            </div>
            {k.okunmamis > 0 && (
              <div style={{
                background: "var(--mavi)",
                color: "#fff",
                borderRadius: "50%",
                width: 20,
                height: 20,
                fontSize: 11,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontWeight: 600
              }}>
                {k.okunmamis}
              </div>
            )}
          </div>
        ))
      )}
    </div>
  );
}
